export interface ConnectorConfig {
  /** Pipedrive API token (from PIPEDRIVE_API_TOKEN env var) */
  apiToken: string
  /** Pipedrive company domain (e.g., 'mycompany' for mycompany.pipedrive.com) */
  companyDomain: string
  /** Injected fetch for testing; defaults to global fetch */
  fetch?: typeof fetch
}

export interface TypeformWebhookPayload {
  event_id: string
  event_type: string
  form_response: {
    form_id: string
    token: string
    submitted_at: string
    answers: Array<{
      type: string
      text?: string
      email?: string
      field: {
        id: string
        type: string
      }
    }>
  }
}

export interface ConnectorResult {
  organizationId: number
  personId: number
  dealId: number
}

function extractField(answers: TypeformWebhookPayload['form_response']['answers'], fieldId: string): string | undefined {
  const answer = answers.find(a => a.field.id === fieldId)
  return answer?.text ?? answer?.email
}

function buildUrl(config: ConnectorConfig, endpoint: string): string {
  return `https://${config.companyDomain}.pipedrive.com/api/v2/${endpoint}?api_token=${config.apiToken}`
}

async function pipedrivePost<T>(config: ConnectorConfig, endpoint: string, body: unknown): Promise<T> {
  const fetchFn = config.fetch ?? fetch
  const url = buildUrl(config, endpoint)
  const response = await fetchFn(url, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify(body),
  })
  if (!response.ok) {
    throw new Error(`Pipedrive API error: ${response.status} ${response.statusText} for ${endpoint}`)
  }
  return response.json() as Promise<T>
}

export async function handle(payload: TypeformWebhookPayload, config: ConnectorConfig): Promise<ConnectorResult> {
  // Validate required fields
  if (!payload.form_response?.answers?.length) {
    throw new Error('Missing form_response.answers in payload')
  }

  const answers = payload.form_response.answers

  // Extract fields using documented field IDs from the example
  const company = extractField(answers, 'company_field_id')
  const name = extractField(answers, 'name_field_id')
  const email = extractField(answers, 'email_field_id')
  const phone = extractField(answers, 'phone_field_id')
  const textAnswer = extractField(answers, 'text_answer_field_id')

  // Organization name: prefer company, fallback to name
  const organizationName = company ?? name
  if (!organizationName) {
    throw new Error('Missing required field: organization name (company or name)')
  }

  // Person name is required
  if (!name) {
    throw new Error('Missing required field: person name')
  }

  // Email is required for person
  if (!email) {
    throw new Error('Missing required field: person email')
  }

  // Step 1: Create organization
  const orgResponse = await pipedrivePost<{ data: { id: number; name: string } }>(
    config,
    'organizations',
    { name: organizationName }
  )
  const organizationId = orgResponse.data.id

  // Step 2: Create person linked to organization
  const personBody: Record<string, unknown> = {
    name,
    org_id: organizationId,
    email: [{ value: email, primary: true, label: 'work' }],
  }
  if (phone) {
    personBody.phone = [{ value: phone, primary: true, label: 'work' }]
  }
  const personResponse = await pipedrivePost<{ data: { id: number } }>(
    config,
    'persons',
    personBody
  )
  const personId = personResponse.data.id

  // Step 3: Create deal linked to person
  // Use first text answer as deal title, fallback to a default
  const dealTitle = textAnswer ?? `Deal from ${name}`
  const dealResponse = await pipedrivePost<{ data: { id: number } }>(
    config,
    'deals',
    { title: dealTitle, person_id: personId }
  )
  const dealId = dealResponse.data.id

  return { organizationId, personId, dealId }
}

import { describe, it, expect, vi, beforeEach } from 'vitest'
import { handle, ConnectorConfig, TypeformWebhookPayload } from './connector'
import {
  SOURCE_EXAMPLE,
  TARGET_ENDPOINTS,
  contractFetch,
  fakeFetch,
  jsonResponse,
  RecordedCall,
} from './fixtures'

describe('contract', () => {
  it('handles the documented example payload', async () => {
    const { fetch, calls } = contractFetch()
    const config: ConnectorConfig = {
      apiToken: 'test-api-token',
      companyDomain: 'testcompany',
      fetch,
    }
    const result = await handle(SOURCE_EXAMPLE as unknown as TypeformWebhookPayload, config)
    expect(calls.length).toBeGreaterThan(0)
    expect(result).toEqual({ organizationId: 123, personId: 456, dealId: 789 })
  })
})

describe('handle', () => {
  let baseConfig: ConnectorConfig
  let calls: RecordedCall[]

  beforeEach(() => {
    const { fetch, calls: recordedCalls } = fakeFetch((req) => {
      if (req.url.includes('/organizations')) return jsonResponse({ data: { id: 1, name: 'Test Org' } }, 201)
      if (req.url.includes('/persons')) return jsonResponse({ data: { id: 2 } }, 201)
      if (req.url.includes('/deals')) return jsonResponse({ data: { id: 3 } }, 201)
      return jsonResponse({ error: 'not found' }, 404)
    })
    calls = recordedCalls
    baseConfig = { apiToken: 'test-token', companyDomain: 'testco', fetch }
  })

  const validPayload = (overrides: Partial<TypeformWebhookPayload> = {}): TypeformWebhookPayload => ({
    event_id: 'evt1',
    event_type: 'form_response',
    form_response: {
      form_id: 'f1',
      token: 't1',
      submitted_at: '2024-01-01T00:00:00Z',
      answers: [
        { type: 'text', text: 'Acme Corp', field: { id: 'company_field_id', type: 'short_text' } },
        { type: 'email', email: 'laura@example.com', field: { id: 'email_field_id', type: 'email' } },
        { type: 'text', text: '555-1234', field: { id: 'phone_field_id', type: 'short_text' } },
        { type: 'text', text: 'Laura', field: { id: 'name_field_id', type: 'short_text' } },
        { type: 'text', text: 'Looking for CRM', field: { id: 'text_answer_field_id', type: 'long_text' } },
      ],
    },
    ...overrides,
  })

  it('creates organization, person, and deal on happy path', async () => {
    const result = await handle(validPayload(), baseConfig)
    expect(result).toEqual({ organizationId: 1, personId: 2, dealId: 3 })
    expect(calls).toHaveLength(3)

    // Check organization creation
    expect(calls[0].method).toBe('POST')
    expect(calls[0].url).toContain('/organizations')
    expect(calls[0].json).toEqual({ name: 'Acme Corp' })

    // Check person creation
    expect(calls[1].method).toBe('POST')
    expect(calls[1].url).toContain('/persons')
    expect(calls[1].json).toEqual({
      name: 'Laura',
      org_id: 1,
      email: [{ value: 'laura@example.com', primary: true, label: 'work' }],
      phone: [{ value: '555-1234', primary: true, label: 'work' }],
    })

    // Check deal creation
    expect(calls[2].method).toBe('POST')
    expect(calls[2].url).toContain('/deals')
    expect(calls[2].json).toEqual({ title: 'Looking for CRM', person_id: 2 })
  })

  it('uses company field for organization name when present', async () => {
    await handle(validPayload(), baseConfig)
    expect(calls[0].json).toEqual({ name: 'Acme Corp' })
  })

  it('falls back to name field for organization name when company missing', async () => {
    const payload = validPayload({
      form_response: {
        ...validPayload().form_response,
        answers: validPayload().form_response.answers.filter(a => a.field.id !== 'company_field_id'),
      },
    })
    await handle(payload, baseConfig)
    expect(calls[0].json).toEqual({ name: 'Laura' })
  })

  it('throws when both company and name are missing', async () => {
    const payload = validPayload({
      form_response: {
        ...validPayload().form_response,
        answers: validPayload().form_response.answers.filter(
          a => a.field.id !== 'company_field_id' && a.field.id !== 'name_field_id'
        ),
      },
    })
    await expect(handle(payload, baseConfig)).rejects.toThrow('Missing required field: organization name')
  })

  it('throws when person name is missing', async () => {
    const payload = validPayload({
      form_response: {
        ...validPayload().form_response,
        answers: validPayload().form_response.answers.filter(a => a.field.id !== 'name_field_id'),
      },
    })
    await expect(handle(payload, baseConfig)).rejects.toThrow('Missing required field: person name')
  })

  it('throws when email is missing', async () => {
    const payload = validPayload({
      form_response: {
        ...validPayload().form_response,
        answers: validPayload().form_response.answers.filter(a => a.field.id !== 'email_field_id'),
      },
    })
    await expect(handle(payload, baseConfig)).rejects.toThrow('Missing required field: person email')
  })

  it('omits phone from person when not provided', async () => {
    const payload = validPayload({
      form_response: {
        ...validPayload().form_response,
        answers: validPayload().form_response.answers.filter(a => a.field.id !== 'phone_field_id'),
      },
    })
    await handle(payload, baseConfig)
    expect(calls[1].json).not.toHaveProperty('phone')
  })

  it('uses text answer for deal title', async () => {
    await handle(validPayload(), baseConfig)
    expect(calls[2].json).toEqual({ title: 'Looking for CRM', person_id: 2 })
  })

  it('falls back to default deal title when text answer missing', async () => {
    const payload = validPayload({
      form_response: {
        ...validPayload().form_response,
        answers: validPayload().form_response.answers.filter(a => a.field.id !== 'text_answer_field_id'),
      },
    })
    await handle(payload, baseConfig)
    expect(calls[2].json).toEqual({ title: 'Deal from Laura', person_id: 2 })
  })

  it('throws on non-2xx response from organizations endpoint', async () => {
    const { fetch, calls: errorCalls } = fakeFetch(() => jsonResponse({ error: 'bad' }, 400))
    const config = { ...baseConfig, fetch }
    await expect(handle(validPayload(), config)).rejects.toThrow('Pipedrive API error: 400 Bad Request for organizations')
  })

  it('throws on non-2xx response from persons endpoint', async () => {
    const { fetch, calls: errorCalls } = fakeFetch((req) =>
      req.url.includes('/organizations') ? jsonResponse({ data: { id: 1 } }, 201) : jsonResponse({ error: 'bad' }, 401)
    )
    const config = { ...baseConfig, fetch }
    await expect(handle(validPayload(), config)).rejects.toThrow('Pipedrive API error: 401 Unauthorized for persons')
  })

  it('throws on non-2xx response from deals endpoint', async () => {
    const { fetch, calls: errorCalls } = fakeFetch((req) => {
      if (req.url.includes('/organizations')) return jsonResponse({ data: { id: 1 } }, 201)
      if (req.url.includes('/persons')) return jsonResponse({ data: { id: 2 } }, 201)
      return jsonResponse({ error: 'bad' }, 500)
    })
    const config = { ...baseConfig, fetch }
    await expect(handle(validPayload(), config)).rejects.toThrow('Pipedrive API error: 500 Internal Server Error for deals')
  })

  it('includes api_token as query parameter in all requests', async () => {
    await handle(validPayload(), baseConfig)
    for (const call of calls) {
      expect(call.url).toContain('api_token=test-token')
    }
  })

  it('uses company domain in all request URLs', async () => {
    await handle(validPayload(), baseConfig)
    for (const call of calls) {
      expect(call.url).toContain('testco.pipedrive.com')
    }
  })
})

